enum Color { RED, BLACK };

struct Node {
    int key;
    Color color;
    Node *left, *right, *parent;
    Node(int k) : key(k), color(RED), left(nullptr), right(nullptr), parent(nullptr) {}
};

Color colorOf(Node* n) { return n ? n->color : BLACK; }   // NIL leaves are always black
Node* parentOf(Node* n) { return n ? n->parent : nullptr; }
Node* grandparentOf(Node* n) { return parentOf(parentOf(n)); }

Node* uncleOf(Node* n) {
    Node* g = grandparentOf(n);
    if (!g) return nullptr;
    return (parentOf(n) == g->left) ? g->right : g->left;
}

void rotateLeft(Node*& root, Node* x) {
    Node* y = x->right;
    x->right = y->left;
    if (y->left) y->left->parent = x;
    y->parent = x->parent;
    if (!x->parent) root = y;
    else if (x == x->parent->left) x->parent->left = y;
    else x->parent->right = y;
    y->left = x;
    x->parent = y;
}

void rotateRight(Node*& root, Node* x) {
    Node* y = x->left;
    x->left = y->right;
    if (y->right) y->right->parent = x;
    y->parent = x->parent;
    if (!x->parent) root = y;
    else if (x == x->parent->right) x->parent->right = y;
    else x->parent->left = y;
    y->right = x;
    x->parent = y;
}

void fixInsert(Node*& root, Node* z) {
    while (colorOf(parentOf(z)) == RED) {
        Node* p = parentOf(z);
        Node* g = grandparentOf(z);
        Node* u = uncleOf(z);

        if (colorOf(u) == RED) {
            // Case 1: uncle is red -> recolor and climb to grandparent
            p->color = BLACK;
            u->color = BLACK;
            g->color = RED;
            z = g;
        } else if (p == g->left) {
            if (z == p->right) {
                // triangle shape: rotate left on parent first
                z = p;
                rotateLeft(root, z);
                p = parentOf(z);
                g = grandparentOf(z);
            }
            // straight line shape: rotate right on grandparent, recolor
            p->color = BLACK;
            g->color = RED;
            rotateRight(root, g);
        } else {
            if (z == p->left) {
                // triangle shape: rotate right on parent first
                z = p;
                rotateRight(root, z);
                p = parentOf(z);
                g = grandparentOf(z);
            }
            // straight line shape: rotate left on grandparent, recolor
            p->color = BLACK;
            g->color = RED;
            rotateLeft(root, g);
        }
    }
    root->color = BLACK; // property two, enforced unconditionally
}

Node* insert(Node*& root, int key) {
    Node* z = new Node(key);
    Node* y = nullptr;
    Node* x = root;
    while (x) {
        y = x;
        x = (z->key < x->key) ? x->left : x->right;
    }
    z->parent = y;
    if (!y) root = z;
    else if (z->key < y->key) y->left = z;
    else y->right = z;

    fixInsert(root, z);
    return z;
}
